# expose group layout for a stacking unit test
s+='''
#[cfg(test)]
mod layout_tests {
    use gpui_kit::{AppContext as _, IntoElement as _, TestAppContext, div};

    use super::{CommandSize, group};

    /// Four slim buttons in a row stack into a column of three, then a column
    /// of one; a full button between slim ones stands alone.
    #[gpui_kit::test]
    fn slim_buttons_stack_three_to_a_column(cx: &mut TestAppContext) {
        use gpui_kit::test::TestWindowExt as _;
        use gpui_kit::component::Root;
        use gpui_kit::{Render, Window, Context, IntoElement, ParentElement as _, Styled as _, InteractiveElement as _, px};

        struct View;
        impl Render for View {
            fn render(&mut self, _: &mut Window, _: &mut Context<Self>) -> impl IntoElement {
                let slim = |id: &'static str| {
                    (
                        CommandSize::Slim,
                        gpui_kit::TestSupportExt::test_support(div().id(id).h(super::SLIM_HEIGHT).w(px(60.)))
                            .into_any_element(),
                    )
                };
                let full = |id: &'static str| {
                    (
                        CommandSize::Full,
                        gpui_kit::TestSupportExt::test_support(div().id(id).h_full().w(px(60.)))
                            .into_any_element(),
                    )
                };
                div().h(super::BODY_CONTENT_HEIGHT).flex().child(group(
                    "Group",
                    vec![slim("a"), slim("b"), slim("c"), slim("d"), full("e"), slim("f")],
                    gpui_kit::black(),
                    gpui_kit::black(),
                    "sans-serif",
                ))
            }
        }
        cx.update(gpui_kit::init);
        let window = cx.add_window(|window, cx| {
            let view = cx.new(|_| View);
            Root::new(view, window, cx)
        });
        cx.update_window(window.into(), |_, window, cx| {
            window.render_frame(cx);
            let at = |id: &str| window.find(id).bounds();
            let (a, b, c, d, e, f) = (at("a"), at("b"), at("c"), at("d"), at("e"), at("f"));
            let gap = super::BODY_PADDING;
            assert_eq!((a.left(), b.left(), c.left()), (a.left(), a.left(), a.left()), "a, b, c aren't one column");
            assert_eq!(b.top() - a.bottom(), gap);
            assert_eq!(c.top() - b.bottom(), gap);
            assert_eq!(d.top(), a.top(), "the fourth doesn't start a new column");
            assert_eq!(d.left() - a.right(), gap);
            assert_eq!(e.left() - d.right(), gap);
            assert_eq!(e.size.height, super::BODY_CONTENT_HEIGHT, "the full button isn't full height");
            assert_eq!((f.top(), f.left() - e.right()), (a.top(), gap));
        })
        .unwrap();
    }
}
'''
open(p,'w').write(s)

