anchor="    /// Clicking a file in the project tree opens it beside the chat history,"
t='''    /// The ribbon's buttons: full ones the height of the body inside its 8px
    /// padding, slim ones 22px tall at the top of their column, 8px apart,
    /// square, each on a background of its own a little apart from the body's.
    #[gpui_kit::test]
    async fn ribbon_buttons_are_full_or_slim_and_square(cx: &mut TestAppContext) {
        use gpui_kit::component::{Theme, ThemeMode};
        cx.update(|cx| {
            gpui_kit::init(cx);
            crate::theme::init(cx);
            piton_syntax::init();
            ProjectDirectory::init(cx);
            ProjectDirectory::set(std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR")), cx);
        });
        let window = cx.add_window(|window, cx| {
            let view = cx.new(|cx| MainWindow::new(window, cx));
            Root::new(view, window, cx)
        });
        let handle = window.into();
        for mode in [ThemeMode::Dark, ThemeMode::Light] {
            cx.update(|cx| Theme::change(mode, None, cx));
            cx.run_until_parked();
            cx.update_window(handle, |_, window, cx| {
                window.render_frame(cx);
                window.simulate_mouse_move(gpui_kit::point(gpui_kit::px(900.), gpui_kit::px(600.)), cx);
                window.render_frame(cx);
                let px = gpui_kit::px;
                let body = window.find("ribbon-controls").bounds();
                let group = window.find("Project").bounds();
                assert_eq!(group.left() - body.left(), px(8.), "{mode:?}: no 8px padding at the left");
                assert_eq!(group.top() - body.top(), px(8.), "{mode:?}: no 8px padding at the top");
                assert_eq!(body.bottom() - group.bottom(), px(8.), "{mode:?}: no 8px padding at the bottom");
                let full = window.find("new-project").bounds();
                let slim = window.find("project-directory").bounds();
                assert_eq!(full.size.height, group.size.height, "{mode:?}: the full button isn't full height");
                assert_eq!(full.top(), group.top());
                assert_eq!(slim.size.height, px(22.), "{mode:?}: the slim button isn't slim");
                assert_eq!(slim.top(), group.top(), "{mode:?}: the slim button isn't at the top");
                assert_eq!(slim.left() - full.right(), px(8.), "{mode:?}: buttons aren't 8px apart");

                let scale = window.scale_factor();
                for button in [full, slim] {
                    let quad = window
                        .painted_quads()
                        .into_iter()
                        .find(|q| {
                            (q.bounds.origin.x.0 - button.left().as_f32() * scale).abs() < 1.
                                && (q.bounds.origin.y.0 - button.top().as_f32() * scale).abs() < 1.
                                && (q.bounds.size.height.0 - button.size.height.as_f32() * scale).abs() < 1.
                                && q.background.as_solid().is_some_and(|c| c.a > 0.)
                        })
                        .unwrap_or_else(|| panic!("{mode:?}: {button:?} has no background of its own"));
                    let radii = quad.corner_radii;
                    assert!(
                        radii.top_left.0 == 0. && radii.top_right.0 == 0. && radii.bottom_left.0 == 0. && radii.bottom_right.0 == 0.,
                        "{mode:?}: {button:?} has rounded corners"
                    );
                    let alpha = quad.background.as_solid().unwrap().a;
                    assert!(alpha < 0.9, "{mode:?}: the background isn't laid over the body");
                }
            })
            .unwrap();
        }
    }

'''
